def solve(data):
    capacity = data['capacity']
    ops = data['ops']
    reads = []
    keys = []
    use = 0
    evicted = 0
    cache = []

    for op, key, value in ops:
        if op == 'put':
            if len(cache) == capacity:
                evicted += 1
                cache.pop(0)
            cache.append((key, value))
            use += 1
        elif op == 'get':
            if key in cache:
                key_index = cache.index((key, value))
                keys.append(key)
                keys.pop(key_index)
                reads.append(value)
                use += 1
            else:
                reads.append(None)
                use += 1

    return {'reads': reads, 'keys': keys}

