def solve(data):
    ttl = data['ttl']
    ops = data['ops']
    reads = []
    keys = []
    current_time = 0

    for op, time, key, value in ops:
        current_time = time
        if op == 'put':
            if key in keys:
                keys.remove(key)
            keys.append(key)
            reads.append(value)
            # Remove expired entries
            keys = [k for k in keys if current_time + ttl > k]
        elif op == 'get':
            if key in keys:
                reads.append(reads[keys.index(key)])
                return reads
            else:
                reads.append(None)
                return reads

    return {'reads': reads, 'keys': sorted(keys)}

